<?php $cnt = ['available' => 0, 'reserved' => 0, 'sold' => 0, 'inactive' => 0]; foreach ($plots as $pl) $cnt[$pl['status']]++; ?>
<div class="page-head"><div><h1><?= e($e['name']) ?></h1><div class="sub"><i class="bi bi-geo-alt me-1"></i><?= e(trim(($e['location'] ? $e['location'] . ', ' : '') . $e['state'])) ?><?= $seller ? ' · Seller: <a href="' . e(url('customers/view', ['id' => $seller['id']])) . '">' . e($seller['full_name']) . '</a>' : '' ?></div></div>
  <div class="d-flex gap-2 flex-wrap"><a class="btn btn-light border" href="<?= e(url('land/estates')) ?>">All estates</a>
  <?php if (can('land.create')): ?><a class="btn btn-light border" href="<?= e(url('land/estate-edit', ['id' => $e['id']])) ?>"><i class="bi bi-pencil me-1"></i>Edit</a><a class="btn btn-primary" href="<?= e(url('land/create', ['estate' => $e['id']])) ?>"><i class="bi bi-plus-lg me-1"></i>Add one plot</a><?php endif; ?>
  <?php if (can('land.delete') && !$plots): ?><form method="post" action="<?= e(url('land/estate-archive')) ?>" data-confirm="Archive this estate?" data-confirm-title="Archive estate" data-confirm-button="Archive"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$e['id'] ?>"><button class="btn btn-light border text-danger"><i class="bi bi-archive"></i></button></form><?php endif; ?></div></div>
<div class="row g-3 mb-3"><?php foreach ([['Available', 'available', 'green'], ['Reserved', 'reserved', 'amber'], ['Sold', 'sold', 'slate']] as [$l, $k, $c]): ?><div class="col-4"><div class="card stat"><span class="ico ico-<?= $c ?>"><i class="bi bi-map"></i></span><span><span class="num d-block"><?= $cnt[$k] ?></span><span class="lbl"><?= $l ?></span></span></div></div><?php endforeach; ?></div>
<?php if (can('land.create')): ?><div class="card mb-3"><div class="card-header">Create many plots at once</div><div class="card-body">
  <?php if (!$e['seller_id']): ?><div class="alert alert-warning py-2 mb-0">Set a seller on this estate first (Edit), because every plot needs a seller.</div><?php else: ?>
  <form method="post" action="<?= e(url('land/bulk-plots')) ?>" class="row g-2 needs-validation" novalidate><?= csrf_field() ?><input type="hidden" name="estate_id" value="<?= (int)$e['id'] ?>">
    <div class="col-6 col-md-2"><label class="form-label">Block</label><input class="form-control" name="block_number" maxlength="30" placeholder="optional"></div>
    <div class="col-6 col-md-2"><label class="form-label">From plot</label><input class="form-control" type="number" name="from" min="1" required></div>
    <div class="col-6 col-md-2"><label class="form-label">To plot</label><input class="form-control" type="number" name="to" min="1" required></div>
    <div class="col-6 col-md-3"><label class="form-label">Price each (₦)</label><input class="form-control" name="list_price" inputmode="decimal"></div>
    <div class="col-6 col-md-2"><label class="form-label">Size</label><input class="form-control" name="size_text" maxlength="60" placeholder="50x100 ft"></div>
    <div class="col-12 col-md-1 d-flex align-items-end"><button class="btn btn-primary w-100">Create</button></div></form>
  <div class="form-text mt-2">Up to 200 at a time. Plots that already exist are skipped. Everything created inherits the estate's seller, location and title status.</div><?php endif; ?></div></div><?php endif; ?>
<div class="card"><div class="card-header">Plots <span class="text-muted fw-normal">(<?= count($plots) ?>)</span></div>
<?php if (!$plots): ?><div class="empty"><i class="bi bi-map"></i>No plots in this estate yet.</div><?php else: ?>
<div class="table-responsive"><table class="table table-hover table-stack align-middle"><thead><tr><th>Plot</th><th>Size</th><th class="text-end">Price</th><th>Status</th></tr></thead><tbody>
<?php foreach ($plots as $r): ?><tr class="row-link" data-href="<?= e(url('land/view', ['id' => $r['id']])) ?>"><td class="cell-main"><a class="fw-semibold text-decoration-none" href="<?= e(url('land/view', ['id' => $r['id']])) ?>"><?= e(($r['block_number'] !== '' ? 'Block ' . $r['block_number'] . ', ' : '') . 'Plot ' . $r['plot_number']) ?></a><div class="small text-muted"><?= e($r['ref']) ?></div></td>
  <td data-label="Size"><?= e($r['size_text'] ?: '–') ?></td><td data-label="Price" class="text-end"><?= e(money($r['list_price'])) ?></td><td data-label="Status"><?= plot_badge($r['status']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
